(function(){const slug=document.body.dataset.slug,x=fc.d.find(v=>v.slug===slug);if(!x)return;document.title=x.seoTitle;document.querySelector('meta[name="description"]').content=x.seoDescription;document.querySelector('meta[property="og:title"]').content=x.seoTitle;document.querySelector('meta[property="og:description"]').content=x.seoDescription;document.querySelector('meta[name="twitter:title"]').content=x.seoTitle;document.querySelector('meta[name="twitter:description"]').content=x.seoDescription;document.querySelector('#formula').textContent=x.formula;document.querySelector('#punchline').textContent=x.punchline;document.querySelector('#description').textContent=x.description;document.querySelector('#category').textContent=x.category;document.querySelector('#art').innerHTML=x.images[0]?`<img class="mock" src="${x.images[0]}" alt="Black shirt mockup with ${x.formula} artwork">`:`<div class="formula-art">${x.formula}<small>${x.punchline}</small></div>`;const c=document.querySelector('#cta');c.innerHTML=x.redbubbleUrl?`<a class="button" data-design="${x.slug}" data-outbound href="${x.redbubbleUrl}" target="_blank" rel="noopener">Get it on Redbubble</a>`:`'<p class="unavailable">Redbubble listing coming soon.</p>'`;const r=document.querySelector('#related');r.innerHTML=fc.d.filter(v=>v.slug!==slug&&v.category===x.category).slice(0,3).map(v=>`<a class="card" href="/designs/${v.slug}/" data-design="${v.slug}"><div class="shirt"></div><div class="formula-art">${v.formula}<small>${v.punchline}</small></div><div class="card-info"><div class="card-category">${v.category}</div><h3 class="card-title">${v.title}</h3></div></a>`).join('')})()
